var RockForms=!0;document.addEventListener("htmx:beforeRequest",(e)=>{if(typeof Nette=="undefined")return;if(e.target.tagName!=="FORM")return;if(!Nette.validateForm(e.target))e.preventDefault();});(()=>{let htmxAdded=!1;"input,focusin".split(",").forEach((event)=>{document.addEventListener(event,(e)=>{if(htmxAdded)return;htmxAdded=!0;if(typeof htmx!=="undefined")return;let script=document.createElement("script");if(typeof htmxAssetUrl=="undefined"){script.src="/site/modules/RockForms/lib/htmx.min.js"}else script.src=htmxAssetUrl;document.head.appendChild(script)})})})();(()=>{let loaded=!1;"input,focusin".split(",").forEach((event)=>{document.addEventListener(event,(e)=>{let form=e.target.closest("form");if(!form)return;let input=form.querySelector('input[name="csrf"]');if(!input)return;if(loaded)return;loaded=!0;input.value="loading";fetch("/rockforms-csrf/",{headers:{"X-Requested-With":"XMLHttpRequest",},}).then((response)=>response.text()).then((tokenValue)=>{input.value=tokenValue}).catch((error)=>{alert("Error fetching CSRF token");console.error(error);input.value=""})})});let resetCSRF=function(){loaded=!1;document.querySelectorAll(".RockForm input[name=csrf]").forEach((input)=>(input.value=""))};document.addEventListener("DOMContentLoaded",resetCSRF);document.addEventListener("htmx:afterSwap",resetCSRF)})()